#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string a;
    cin >> a;
    string b;
    cin >> b;

    vector<int> ca(26, 0), cb(26, 0);
    for (char ch : a) ca[ch - 'a']++;
    for (char ch : b) cb[ch - 'a']++;
    bool ok = true;
    for (int c = 0; c < 26; c++) {
        if ((ca[c] == 0) != (cb[c] == 0)) ok = false;
    }
    sort(ca.begin(), ca.end());
    sort(cb.begin(), cb.end());
    if (ca != cb) ok = false;
    cout << (ok ? "yes" : "no") << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        String b = sc.next();

        int[] ca = new int[26], cb = new int[26];
        for (int i = 0; i < a.length(); i++) ca[a.charAt(i) - 'a']++;
        for (int i = 0; i < b.length(); i++) cb[b.charAt(i) - 'a']++;
        boolean ok = true;
        for (int c = 0; c < 26; c++) {
            if ((ca[c] == 0) != (cb[c] == 0)) ok = false;
        }
        Arrays.sort(ca);
        Arrays.sort(cb);
        if (!Arrays.equals(ca, cb)) ok = false;
        System.out.println(ok ? "yes" : "no");
    }
}
